export default function TopBar({ componentCount, versionCount, redditCount, pageCount }) {
    return (
      <div className="top-bar">
        <span>Releasetrain <span style={{ color: "#4da6ff" }}>v3.1.0</span></span>
        <span>Components: <span style={{ color: "#4da6ff" }}>{componentCount}</span></span>
        <span>Versions: <span style={{ color: "#4da6ff" }}>{versionCount}</span></span>
        <span>Reddit: <span style={{ color: "#4da6ff" }}>{redditCount}</span></span>
        <span>Page Versions: <span style={{ color: "#4da6ff" }}>{pageCount}</span></span>
        <a href="https://github.com/antrunner/releasetrain-client" target="_blank" rel="noreferrer">GitHub ↗</a>
      </div>
    );
  }
